resource "aws_security_group" "sg-ssm-endpoint" {
  name        = "${var.project_name}-${var.account_abbr}-sg-ssm-endpoint"
  description = "Security group for SSM endpoint"
  vpc_id      = aws_vpc.sh-vpc.id

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]

