resource "aws_route53_zone" "rt53-uw2-bedrock" {
  name = "bedrock.us-west-2.amazonaws.com"

  vpc {
    vpc_id = aws_vpc.sh-vpc.id
  }
  vpc {
    vpc_id     = aws_vpc.sh-uw2-vpc.id
    vpc_region = "us-west-2"
  }

  lifecycle {
    ignore_changes = [vpc]
  }
}

